// Command ctc-sim is the CamelliaTraceabilityCloud device simulator
// (specs/03.11): it makes development and demos possible with no real devices.
//
// Simulated device families:
//   - WEATHER_STATION / SOIL_SENSOR: periodic telemetry over MQTT
//   - UAV / MOWER: watch NATS mission.started events, fly/mow the route,
//     publish GPS telemetry and report mission progress over HTTPS
//     (device-gateway) until completion, which triggers the trace event.
//
// Credentials come from data/seed-devices.json (generated by `ctc-api -mode seed`)
// or from environment variables (CTC_SIM_TENANT + CTC_SIM_DEVICES as JSON).
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log/slog"
	"math"
	"math/rand"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/nats-io/nats.go"

	"github.com/ouyang6559/CamelliaTraceabilityCloud/adapters/device"
	mqttadapter "github.com/ouyang6559/CamelliaTraceabilityCloud/adapters/device/genericmqtt"
	"github.com/ouyang6559/CamelliaTraceabilityCloud/packages/mqttclient"
)

type simDevice struct {
	ID       string `json:"id"`
	Token    string `json:"token"`
	Code     string `json:"-"`
	Type     string `json:"-"`
	LastSeen time.Time
	Battery  int
}

type simConfig struct {
	TenantID string `json:"tenant_id"`
	Devices  map[string]struct {
		ID    string `json:"id"`
		Token string `json:"token"`
	} `json:"devices"`
}

var deviceTypeByCode = map[string]string{
	"DEV-WS-001":   "WEATHER_STATION",
	"DEV-SOIL-001": "SOIL_SENSOR",
	"DEV-UAV-001":  "UAV",
	"DEV-MOW-001":  "MOWER",
}

func main() {
	configPath := flag.String("config", "data/seed-devices.json", "path to seed-devices.json")
	apiURL := flag.String("api", envOr("CTC_API_URL", "http://localhost:8080"), "API base URL")
	mqttURL := flag.String("mqtt", envOr("CTC_MQTT_URL", "tcp://localhost:1883"), "MQTT broker URL")
	natsURL := flag.String("nats", envOr("CTC_NATS_URL", "nats://localhost:4222"), "NATS URL")
	interval := flag.Duration("interval", 5*time.Second, "static telemetry interval")
	flag.Parse()

	log := slog.New(slog.NewTextHandler(os.Stdout, nil))
	log.Info("ctc-sim starting", "config", *configPath, "mqtt", *mqttURL)

	cfgRaw, err := os.ReadFile(*configPath)
	if err != nil {
		log.Error("cannot read simulator config (run `ctc-api -mode seed` first or pass -config)", "err", err)
		os.Exit(1)
	}
	var cfg simConfig
	if err := json.Unmarshal(cfgRaw, &cfg); err != nil {
		log.Error("invalid simulator config", "err", err)
		os.Exit(1)
	}
	var devices []simDevice
	for code, d := range cfg.Devices {
		devices = append(devices, simDevice{
			ID: d.ID, Token: d.Token, Code: code,
			Type:    deviceTypeByCode[code],
			Battery: 95,
		})
	}
	if len(devices) == 0 {
		log.Error("no devices in simulator config")
		os.Exit(1)
	}
	log.Info("simulated devices", "count", len(devices), "tenant", cfg.TenantID)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	mqttClient, err := mqttclient.Connect(ctx, *mqttURL, fmt.Sprintf("ctc-sim-%d", time.Now().UnixNano()%100000),
		nil, nil, log)
	if err != nil {
		log.Warn("mqtt unavailable; telemetry will retry in background", "err", err)
	}

	// Device Adapter SDK reference implementation is used to publish
	// telemetry/missions over MQTT (specs/20).
	adapter, err := mqttadapter.New(*mqttURL, log)
	if err == nil {
		manifest := mqttadapter.Manifest()
		log.Info("device adapter loaded", "name", manifest.Name, "version", manifest.Version,
			"protocols", fmt.Sprint(manifest.Protocols))
	} else {
		log.Warn("mqtt adapter unavailable; falling back to direct publish", "err", err)
	}
	_ = adapter

	// NATS: watch mission execution envelopes.
	var natsConn *nats.Conn
	for attempt := 1; attempt <= 10; attempt++ {
		natsConn, err = nats.Connect(*natsURL, nats.Timeout(3*time.Second))
		if err == nil {
			break
		}
		time.Sleep(time.Duration(attempt) * time.Second)
	}
	if natsConn != nil {
		subj := "ctc." + cfg.TenantID + ".mission.started"
		if _, err := natsConn.Subscribe(subj, func(m *nats.Msg) {
			handleMissionStarted(ctx, m.Data, cfg.TenantID, devices, mqttClient, *apiURL, log)
		}); err != nil {
			log.Warn("nats subscribe failed", "err", err)
		} else {
			log.Info("subscribed for missions", "subject", subj)
		}
	} else {
		log.Warn("nats unavailable; mission simulation disabled")
	}

	// Static device telemetry loop.
	go func() {
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				for i := range devices {
					d := &devices[i]
					switch d.Type {
					case "WEATHER_STATION":
						publishStatic(mqttClient, cfg.TenantID, d.Code, d.Token, map[string]float64{
							"temperature": 24 + 8*math.Sin(float64(time.Now().Unix())/6000) + rnd(1.5),
							"humidity":    72 + rnd(8),
							"rainfall":    rnd(0.4),
							"wind_speed":  1.5 + rnd(2),
							"pressure":    1008 + rnd(4),
							"light":       38000 + rnd(9000),
						})
					case "SOIL_SENSOR":
						publishStatic(mqttClient, cfg.TenantID, d.Code, d.Token, map[string]float64{
							"soil_moisture":    28 + rnd(9),
							"soil_temperature": 19 + rnd(3),
							"ph":               5.4 + rnd(0.3),
							"ec":               0.6 + rnd(0.2),
							"npk_n":            55 + rnd(12),
							"npk_p":            22 + rnd(6),
							"npk_k":            78 + rnd(14),
						})
					}
				}
			}
		}
	}()

	log.Info("ctc-sim running; press Ctrl+C to stop")
	<-ctx.Done()
	log.Info("bye")
}

// handleMissionStarted simulates executing a mission route on the owning robot.
func handleMissionStarted(ctx context.Context, payload []byte, tenantID string, devices []simDevice, mqttClient *mqttclient.MQTTClient, apiURL string, log *slog.Logger) {
	var envelope struct {
		MissionID   string            `json:"mission_id"`
		DeviceID    string            `json:"device_id"`
		MissionType string            `json:"mission_type"`
		Route       []device.Waypoint `json:"route"`
	}
	if err := json.Unmarshal(payload, &envelope); err != nil {
		log.Warn("mission envelope invalid", "err", err)
		return
	}
	var owner *simDevice
	for i := range devices {
		if devices[i].ID == envelope.DeviceID {
			owner = &devices[i]
			break
		}
	}
	if owner == nil {
		return // mission for another tenant/device
	}
	if len(envelope.Route) < 2 {
		log.Warn("mission route too short", "mission", envelope.MissionID)
		return
	}
	log.Info("simulating mission", "mission", envelope.MissionID, "device", owner.Code,
		"type", envelope.MissionType, "waypoints", len(envelope.Route))

	go func() {
		steps := len(envelope.Route)
		for step := 1; step <= steps; step++ {
			wp := envelope.Route[step-1]
			owner.Battery -= 2
			if owner.Battery < 20 {
				owner.Battery = 20
			}
			telemetry := map[string]any{
				"device_code":   owner.Code,
				"token":         owner.Token,
				"ts":            time.Now().UTC(),
				"status":        "online",
				"battery_level": owner.Battery,
				"metrics": map[string]float64{
					"speed":    wp.Speed,
					"altitude": wp.Alt,
				},
				"position": map[string]float64{"lat": wp.Lat, "lng": wp.Lng},
			}
			publishRaw(mqttClient, tenantID, owner.Code, telemetry, log)
			reportProgress(ctx, apiURL, envelope.MissionID, map[string]any{
				"device_code": owner.Code,
				"token":       owner.Token,
				"progress":    float64(step) / float64(steps) * 100,
				"latitude":    wp.Lat,
				"longitude":   wp.Lng,
				"note":        "waypoint " + fmt.Sprint(step) + "/" + fmt.Sprint(steps) + " (" + wp.Action + ")",
			}, log)
			time.Sleep(1200 * time.Millisecond)
		}
		log.Info("mission simulation finished", "mission", envelope.MissionID)
	}()
}

func publishStatic(client *mqttclient.MQTTClient, tenantID, code, token string, metrics map[string]float64) {
	if client == nil {
		return
	}
	msg := map[string]any{
		"device_code": code,
		"token":       token,
		"ts":          time.Now().UTC(),
		"status":      "online",
		"metrics":     metrics,
	}
	_ = client.Publish(fmt.Sprintf("ctc/v1/tenants/%s/devices/%s/telemetry", tenantID, code), 0, false, msg)
}

func publishRaw(client *mqttclient.MQTTClient, tenantID, code string, msg map[string]any, log *slog.Logger) {
	if client == nil {
		return
	}
	if err := client.Publish(fmt.Sprintf("ctc/v1/tenants/%s/devices/%s/telemetry", tenantID, code), 0, false, msg); err != nil {
		log.Warn("telemetry publish failed", "device", code, "err", err)
	}
}

func reportProgress(ctx context.Context, apiURL, missionID string, body map[string]any, log *slog.Logger) {
	data, _ := json.Marshal(body)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost,
		strings.TrimRight(apiURL, "/")+"/api/v1/device-gateway/missions/"+missionID+"/progress",
		strings.NewReader(string(data)))
	if err != nil {
		return
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		log.Warn("progress report failed", "mission", missionID, "err", err)
		return
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		log.Warn("progress report rejected", "mission", missionID, "status", resp.StatusCode)
	}
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func rnd(scale float64) float64 {
	return (rand.Float64()*2 - 1) * scale
}
